package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for MathUtils.factorialDouble
 */
public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double EPSILON = 1e-6;











    @Test
    public void testFactorialDouble_BoundaryLargeN() {
        // Testing the branch: if (n >= 21)
        // This uses the Math.exp(factorialLog(n)) path
        // 21! is approximately 5.109094217170944e+19
        double result = MathUtils.factorialDouble(21);
        double expected = 5.109094217170944E19; 
        // Using a relative delta for very large numbers
        assertEquals(expected, result, expected * 1e-15);
    }


}

