 */
public class MathUtils_factorialDouble_TriageGen2Test {

    private static final double EPSILON = 1e-6;













    @Test
    public void testFactorialDouble_LargeN() {
        // Testing a larger N to ensure the log/exp path handles growth
        // 30! is approx 2.65252859812191e+32
        double result = MathUtils.factorialDouble(30);
        double expected = 2.65252859812191e+32;
        assertEquals(expected, result, expected * 1e-14);
    }
